import hashlib,json,statistics
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
def identity(rel):
 p=ROOT/rel;h=hashlib.sha256()
 with p.open('rb')as f:
  for b in iter(lambda:f.read(1024*1024),b''):h.update(b)
 return {'path':rel,'bytes':p.stat().st_size,'sha256':h.hexdigest()}
def write(rel,obj): (ROOT/rel).write_text(json.dumps(obj,indent=2)+'\n')
def evidence(rel):
 d=json.loads((ROOT/rel).read_text());return {'path':rel,'evidence_id':d['structuredContent']['evidence_id']}
